  1→import axios from 'axios';
  2→import { WhatsAppLine, MessageTemplate } from '../../models/sequelize/associations.js';
  3→
  4→/**
  5→ * TemplateManager - Handles Meta WhatsApp template management
  6→ * Submits templates to Meta for approval and manages template lifecycle
  7→ */
  8→class TemplateManager {
  9→  constructor() {
 10→    this.baseUrl = 'https://graph.facebook.com/v18.0';
 11→  }
 12→
 13→  /**
 14→   * Submit a template to Meta for approval
 15→   * @param {Object} template - Template object from database
 16→   * @param {Object} line - WhatsApp line with credentials
 17→   * @returns {Promise<Object>} Meta API response
 18→   */
 19→  async submitTemplate(template, line) {
 20→    try {
 21→      const url = `${this.baseUrl}/${line.business_account_id}/message_templates`;
 22→
 23→      // Parse variables if stored as string
 24→      let variables = template.variables;
 25→      if (typeof variables === 'string') {
 26→        variables = JSON.parse(variables);
 27→      }
 28→
 29→      // Build components for Meta API
 30→      const components = this._buildTemplateComponents(template, variables);
 31→
 32→      const payload = {
 33→        name: this._sanitizeTemplateName(template.name),
 34→        language: template.language || 'es',
 35→        category: template.category || 'UTILITY',
 36→        components
 37→      };
 38→
 39→      console.log('🔍 [DEBUG TEMPLATE MANAGER] Full payload to Meta:', JSON.stringify(payload, null, 2));
 40→
 41→      const response = await axios.post(url, payload, {
 42→        headers: {
 43→          'Authorization': `Bearer ${line.access_token}`,
 44→          'Content-Type': 'application/json'
 45→        }
 46→      });
 47→
 48→      // Update template with Meta template ID
 49→      await template.update({
 50→        meta_template_id: response.data.id,
 51→        status: 'pending'
 52→      });
 53→
 54→      return response.data;
 55→    } catch (error) {
 56→      console.error('Error submitting template to Meta:', error.response?.data || error.message);
 57→
 58→      // Update template to rejected status with error message
 59→      if (template) {
 60→        await template.update({
 61→          status: 'rejected',
 62→          rejection_reason: error.response?.data?.error?.message || error.message
 63→        });
 64→      }
 65→
 66→      throw new Error(error.response?.data?.error?.message || 'Failed to submit template to Meta');
 67→    }
 68→  }
 69→
 70→  /**
 71→   * Get template status from Meta
 72→   * @param {string} metaTemplateId - Meta's template ID
 73→   * @param {string} accessToken - WhatsApp line access token
 74→   * @returns {Promise<Object>} Template status from Meta
 75→   */
 76→  async getTemplateStatus(metaTemplateId, accessToken) {
 77→    try {
 78→      const url = `${this.baseUrl}/${metaTemplateId}`;
 79→
 80→      const response = await axios.get(url, {
 81→        headers: {
 82→          'Authorization': `Bearer ${accessToken}`
 83→        },
 84→        params: {
