130→   * @param {Object} params.headerParams - Parameters for header (text or media)
131→   * @param {Array} params.buttonParams - Parameters for dynamic buttons
132→   * @returns {Promise<Object>} Meta API response
133→   */
134→  async sendTemplateMessage({ line, to, template, variableValues = [], headerParams = {}, buttonParams = [], headerCaption = null }) {
135→    try {
136→      console.log('\n🔍 ========== TEMPLATE MANAGER - SEND TEMPLATE MESSAGE ==========');
137→      console.log('📋 Template:', template.name, '(ID:', template.id, ')');
138→      console.log('📋 Header Type:', template.header_type);
139→      console.log('📋 Header Content:', template.header_content);
140→      console.log('📋 Header Caption (template):', template.header_caption);
141→      console.log('📥 headerParams received:', JSON.stringify(headerParams, null, 2));
142→      console.log('📥 headerCaption received:', headerCaption);
143→      console.log('📥 variableValues:', JSON.stringify(variableValues, null, 2));
144→      console.log('📥 buttonParams:', JSON.stringify(buttonParams, null, 2));
145→      console.log('===============================================\n');
146→
147→      if (template.status !== 'approved') {
148→        throw new Error('Template must be approved before sending');
149→      }
150→
151→      const url = `${this.baseUrl}/${line.phone_number_id}/messages`;
152→
153→      // Parse variables and buttons if needed
154→      let variables = template.variables;
155→      if (typeof variables === 'string') {
156→        variables = JSON.parse(variables);
157→      }
158→
159→      let buttons = template.buttons;
160→      if (typeof buttons === 'string') {
161→        buttons = JSON.parse(buttons);
162→      }
163→
164→      // Build components for sending
165→      const components = [];
166→
167→      // 1. HEADER parameters (if header has variables or media)
168→      if (template.header_type && template.header_type !== 'NONE') {
169→        console.log('🔍 Processing header type:', template.header_type);
170→        const headerComponent = { type: 'header' };
171→
172→        if (template.header_type === 'TEXT' && headerParams.text) {
173→          // Header with text variables
174→          headerComponent.parameters = [{
175→            type: 'text',
176→            text: headerParams.text
177→          }];
178→          components.push(headerComponent);
179→        } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(template.header_type)) {
180→          // Media header
181→          const mediaType = template.header_type.toLowerCase();
182→          console.log('🔍 Media type:', mediaType);
183→
184→          // If headerParams provided, use that. Otherwise, use header_content (public URL)
185→          let mediaParam = headerParams[mediaType];
186→          console.log('🔍 mediaParam from headerParams[' + mediaType + ']:', JSON.stringify(mediaParam, null, 2));
187→
188→          if (!mediaParam && template.header_content) {
189→            console.log('🔍 No mediaParam, checking template.header_content:', template.header_content);
190→            // Check if header_content is a valid URL (not a handle like h:xxxxx)
191→            if (template.header_content.startsWith('http://') || template.header_content.startsWith('https://')) {
192→              // Use the public URL saved in header_content
193→              mediaParam = { link: template.header_content };
194→              console.log('✅ Using template default URL:', mediaParam);
195→            } else if (template.header_content.startsWith('h:')) {
196→              // This is a handle, not a URL - cannot be used for sending messages
197→              console.error('❌ Template has media handle but no public URL');
198→              throw new Error(`Template "${template.name}" has a media handle but no public URL. Please re-upload the media file.`);
199→            } else {
200→              console.warn('⚠️ template.header_content exists but is not a valid URL or handle:', template.header_content);
201→            }
202→          }
203→
204→          if (mediaParam) {
205→            console.log('✅ mediaParam is available:', JSON.stringify(mediaParam, null, 2));
206→            if (mediaType === 'document') {
207→              // For DOCUMENTS: filename is the name shown when downloading the file
208→              // The headerCaption or template.header_caption should be used as the filename
209→
210→              // Build the document parameter
211→              const docParam = { ...mediaParam };
212→
213→              // Set filename (priority: 1. from upload, 2. headerCaption, 3. template.header_caption)
214→              if (!docParam.filename && (headerCaption || template.header_caption)) {
215→                docParam.filename = headerCaption || template.header_caption;
216→              }
217→
218→              mediaParam = docParam;
219→
220→            } else if (mediaType === 'image' || mediaType === 'video') {
221→              // For images/videos: only caption field
222→              // Priority: headerCaption > template.header_caption
223→              const caption = headerCaption || template.header_caption;
224→
225→              if (caption) {
226→                mediaParam = {
227→                  ...mediaParam,
228→                  caption: caption
229→                };
230→              }
231→            }
232→
233→            console.log('📤 Final mediaParam to send:', JSON.stringify(mediaParam, null, 2));
234→            headerComponent.parameters = [{
235→              type: mediaType,
236→              [mediaType]: mediaParam
237→            }];
238→            components.push(headerComponent);
239→          } else {
240→            console.error('❌ NO mediaParam available! Template requires ' + mediaType + ' header but none provided');
241→            console.error('❌ This will cause Meta API error: "Either one of media ID or link must be present"');
242→          }
243→        }
244→      }
245→
246→      // 2. BODY parameters
247→      if (variableValues.length > 0) {
248→        const bodyParameters = variableValues.map((value) => ({
249→          type: 'text',
250→          text: value.toString()
251→        }));
252→
253→        components.push({
254→          type: 'body',
255→          parameters: bodyParameters
256→        });
257→      }
258→
259→      // 3. BUTTON parameters (for URL buttons with variables or COPY_CODE)
260→      if (buttons && buttons.length > 0 && buttonParams.length > 0) {
261→        buttonParams.forEach((param) => {
262→          if (param.type === 'url' && param.text) {
263→            // URL button with dynamic suffix
264→            components.push({
265→              type: 'button',
266→              sub_type: 'url',
267→              index: param.index,
268→              parameters: [{
269→                type: 'text',
270→                text: param.text
271→              }]
272→            });
273→          } else if (param.type === 'copy_code' && param.code) {
274→            // Copy code button
275→            components.push({
276→              type: 'button',
277→              sub_type: 'copy_code',
278→              index: param.index,
279→              parameters: [{
280→                type: 'coupon_code',
281→                coupon_code: param.code
282→              }]
283→            });
284→          }
285→        });
286→      }
287→
288→      const payload = {
289→        messaging_product: 'whatsapp',
290→        to: to.replace(/\+/g, ''),
291→        type: 'template',
292→        template: {
293→          name: this._sanitizeTemplateName(template.name),
294→          language: {
295→            code: template.language || 'es'
296→          },
297→          components
298→        }
299→      };
300→
301→      console.log('📤 Final payload to Meta API:', JSON.stringify(payload, null, 2));
302→
303→      const response = await axios.post(url, payload, {
304→        headers: {
305→          'Authorization': `Bearer ${line.access_token}`,
306→          'Content-Type': 'application/json'
307→        }
308→      });
309→
310→      return response.data;
311→    } catch (error) {
312→      console.error('Error sending template message:', error.response?.data || error.message);
313→      throw new Error(error.response?.data?.error?.message || 'Failed to send template message');
314→    }
315→  }
