344→  /**
345→   * Build Meta template components from template object
346→   * Supports HEADER, BODY, FOOTER, and BUTTONS
347→   * @param {Object} template - Complete template object
348→   * @param {Array} variables - Variable definitions
349→   * @returns {Array} Meta template components
350→   * @private
351→   */
352→  _buildTemplateComponents(template, variables = []) {
353→    const components = [];
354→
355→    // 1. HEADER Component (optional)
356→    if (template.header_type && template.header_type !== 'NONE') {
357→      const header = { type: 'HEADER' };
358→
359→      if (template.header_type === 'TEXT') {
360→        header.format = 'TEXT';
361→        header.text = template.header_content;
362→
363→        // Check if header has variables
364→        if (template.header_example?.header_text) {
365→          header.example = {
366→            header_text: Array.isArray(template.header_example.header_text)
367→              ? template.header_example.header_text
368→              : [template.header_example.header_text]
369→          };
370→        }
371→      } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(template.header_type)) {
372→        header.format = template.header_type;
373→
374→        console.log('🔍 [DEBUG TEMPLATE MANAGER] Building media header for type:', template.header_type);
375→        console.log('🔍 [DEBUG TEMPLATE MANAGER] header_example from DB:', template.header_example);
376→
377→        // IMPORTANT: Meta REQUIRES an example with the sample file handle for media headers
378→        if (template.header_example?.header_handle) {
379→          header.example = {
380→            header_handle: Array.isArray(template.header_example.header_handle)
381→              ? template.header_example.header_handle
382→              : [template.header_example.header_handle]
383→          };
384→          console.log('✅ [TEMPLATE MANAGER] Media header example included:', header.example);
385→        } else {
386→          console.warn('⚠️  [TEMPLATE MANAGER] No header_example found - Meta will reject this template!');
387→        }
388→      } else if (template.header_type === 'LOCATION') {
389→        header.format = 'LOCATION';
390→      }
391→
392→      components.push(header);
393→    }
394→
395→    // 2. BODY Component (required)
396→    const bodyComponent = {
397→      type: 'BODY',
398→      text: template.content
399→    };
400→
401→    if (variables && variables.length > 0) {
402→      bodyComponent.example = {
403→        body_text: [variables.map(v => v.example || `[${v.name}]`)]
404→      };
405→    }
406→
407→    components.push(bodyComponent);
408→
409→    // 3. FOOTER Component (optional)
410→    if (template.footer_text) {
411→      components.push({
412→        type: 'FOOTER',
413→        text: template.footer_text
414→      });
415→    }
416→
417→    // 4. BUTTONS Component (optional)
418→
419→    let buttons = JSON.parse(template.buttons);
420→
421→    console.log('Building buttons component with buttons:', buttons);
422→
423→    if (buttons && buttons.length > 0) {
424→      const buttonsComponent = {
425→        type: 'BUTTONS',
426→        buttons: buttons.map(btn => {
427→          if (btn.type === 'QUICK_REPLY') {
428→            return {
429→              type: 'QUICK_REPLY',
430→              text: btn.text
431→            };
432→          } else if (btn.type === 'URL') {
433→            const urlButton = {
434→              type: 'URL',
435→              text: btn.text,
436→              url: btn.url
437→            };
438→
439→            // Support for dynamic URLs with {{1}}
440→            if (btn.url && btn.url.includes('{{1}}')) {
441→              urlButton.example = [btn.url_example || 'https://example.com'];
442→            }
443→
444→            return urlButton;
445→          } else if (btn.type === 'PHONE_NUMBER') {
446→            return {
447→              type: 'PHONE_NUMBER',
448→              text: btn.text,
449→              phone_number: btn.phone_number
450→            };
451→          } else if (btn.type === 'COPY_CODE') {
452→            return {
453→              type: 'COPY_CODE',
454→              example: btn.code_example || '123456'
455→            };
456→          }
457→
458→          return null;
459→        }).filter(Boolean) // Remove any null buttons
460→      };
461→
462→      if (buttonsComponent.buttons.length > 0) {
463→        components.push(buttonsComponent);
464→      }
465→    }
466→
467→    return components;
468→  }
