470→  /**
471→   * Validate buttons configuration
472→   * @param {Array} buttons - Array of button objects
473→   * @throws {Error} If validation fails
474→   * @private
475→   */
476→  _validateButtons(buttons) {
477→    if (!buttons || buttons.length === 0) return true;
478→
479→    const counts = {
480→      QUICK_REPLY: 0,
481→      URL: 0,
482→      PHONE_NUMBER: 0,
483→      COPY_CODE: 0
484→    };
485→
486→    buttons.forEach(btn => {
487→      if (counts[btn.type] !== undefined) {
488→        counts[btn.type]++;
489→      }
490→    });
491→
492→    // Check limits
493→    if (counts.QUICK_REPLY > 10) {
494→      throw new Error('Máximo 10 botones Quick Reply permitidos');
495→    }
496→    if (counts.URL > 2) {
497→      throw new Error('Máximo 2 botones URL permitidos');
498→    }
499→    if (counts.PHONE_NUMBER > 1) {
500→      throw new Error('Máximo 1 botón Phone Number permitido');
501→    }
502→    if (counts.COPY_CODE > 1) {
503→      throw new Error('Máximo 1 botón Copy Code permitido');
504→    }
505→    if (buttons.length > 10) {
506→      throw new Error('Máximo 10 botones en total');
507→    }
508→
509→    // Validate button text length
510→    buttons.forEach((btn, index) => {
511→      if (btn.text && btn.text.length > 25) {
512→        throw new Error(`Botón ${index + 1}: El texto no puede exceder 25 caracteres`);
513→      }
514→    });
515→
516→    return true;
517→  }
518→
519→  /**
520→   * Sanitize template name for Meta API
521→   * Meta requires lowercase, underscores only
522→   * @param {string} name - Template name
523→   * @returns {string} Sanitized name
524→   * @private
525→   */
526→  _sanitizeTemplateName(name) {
527→    return name
528→      .toLowerCase()
529→      .replace(/\s+/g, '_')
530→      .replace(/[^a-z0-9_]/g, '')
531→      .substring(0, 512); // Meta limit
532→  }
533→
534→  /**
535→   * Sync template status from Meta
536→   * Fetches status from Meta and updates local database
537→   * @param {number} templateId - Local template ID
538→   * @returns {Promise<Object>} Updated template
539→   */
540→  async syncTemplateStatus(templateId) {
541→    try {
542→      const template = await MessageTemplate.findByPk(templateId, {
543→        include: [{
544→          model: WhatsAppLine,
545→          as: 'line'
546→        }]
547→      });
548→
549→      if (!template || !template.meta_template_id) {
550→        throw new Error('Template not found or not submitted to Meta');
551→      }
552→
553→      const metaStatus = await this.getTemplateStatus(
554→        template.meta_template_id,
555→        template.line.access_token
556→      );
557→
558→      // Map Meta status to our status
559→      const statusMap = {
560→        'APPROVED': 'approved',
561→        'PENDING': 'pending',
562→        'REJECTED': 'rejected'
563→      };
564→
565→      const newStatus = statusMap[metaStatus.status] || template.status;
566→
567→      if (newStatus !== template.status) {
568→        await template.update({
569→          status: newStatus,
570→          rejection_reason: metaStatus.status === 'REJECTED' ? metaStatus.rejection_reason : null
571→        });
572→      }
573→
574→      return template;
575→    } catch (error) {
576→      console.error('Error syncing template status:', error);
577→      throw error;
578→    }
579→  }
580→}
581→
582→export default new TemplateManager();
