 30→    if (content.length <= maxLength) return content;
 31→    return content.substring(0, maxLength) + '...';
 32→  };
 33→
 34→  if (loading) {
 35→    return (
 36→      <div className="template-list-loading">
 37→        <Spinner animation="border" variant="primary" />
 38→        <p className="mt-3">Cargando plantillas...</p>
