 59→              <div className="template-card-content">
 60→                <div className="template-card-header">
 61→                  <h6 className="template-card-title">{template.name}</h6>
 62→                  {getStatusBadge(template.status)}
 63→                </div>
 64→                <p className="template-card-text">
 65→                  {truncateContent(template.content)}
 66→                </p>
 67→                {template.line && (
 68→                  <p className="template-card-line">
 69→                    <i className="bi bi-whatsapp me-1"></i>
 70→                    {template.line.company_name}
 71→                  </p>
 72→                )}
 73→              </div>
 74→
 75→              {/* Mostrar botones solo si tiene permisos y no está en revisión por Meta */}
 76→              {(onEdit || onDelete) && template.status !== 'pending' && (
 77→                <div className="template-card-actions">
 78→                  {onEdit && (
 79→                    <Button
 80→                      variant="outline-dark"
 81→                      className="template-action-btn"
 82→                      onClick={() => onEdit(template)}
 83→                      title="Editar"
 84→                    >
 85→                      <i className="bi bi-pencil"></i>
 86→                    </Button>
 87→                  )}
 88→                  {onDelete && (
 89→                    <Button
 90→                      variant="outline-danger"
