132→      }
133→
134→      // Normalize phone number to ensure consistency (with + prefix)
135→      const normalizedPhone = normalizePhoneNumber(from);
136→
137→      // Find or create lead
138→      const contactInfo = contacts?.find(c => c.wa_id === from);
139→      const leadName = contactInfo?.profile?.name || null;
140→
141→      const { lead } = await LeadService.findOrCreateLead({
142→        phone_number: normalizedPhone, // Use normalized phone with + prefix
143→        name: leadName,
144→        first_contact_date: new Date(parseInt(timestamp) * 1000),
145→      });
146→
147→      // Extract message content based on type
148→      let messageContent = '';
149→      let fileUrl = null;
150→      let messageType = 'text';
151→      let interactiveType = null;
152→      let interactiveData = null;
153→
154→
155→
156→      switch (type) {
157→        case 'text':
158→          messageContent = message.text?.body || '';
159→          messageType = 'text';
160→          break;
161→
162→        case 'image':
163→          messageContent = message.image?.caption || '[Image]';
164→          fileUrl = message.image?.id || null; // Store media ID, actual URL retrieved later
165→          messageType = 'image';
