179→
180→        case 'document':
181→          messageContent = message.document?.filename || '[Document]';
182→          fileUrl = message.document?.id || null;
183→          messageType = 'document';
184→          break;
185→
186→        case 'interactive':
187→          // Handle interactive message responses (button clicks, list selections)
188→          if (message.interactive?.type === 'button_reply') {
189→            // Quick reply button response
190→            const buttonReply = message.interactive.button_reply;
191→            messageContent = buttonReply?.title || '[Button Response]';
192→            messageType = 'interactive';
193→            interactiveType = 'button_reply';
194→            interactiveData = {
