399→      }
400→
401→      // Map Meta status to our status values
402→      const statusMap = {
403→        sent: 'sent',
404→        delivered: 'delivered',
405→        read: 'read',
406→        failed: 'failed',
407→      };
408→
409→      const mappedStatus = statusMap[newStatus];
410→      if (!mappedStatus) {
411→        return null;
412→      }
413→
414→      const updatedMessage = await MessageService.updateMessageStatus(
415→        meta_message_id,
416→        mappedStatus
417→      );
418→
419→      if (updatedMessage) {
420→        // Emit Socket.IO event for status update
421→        SocketService.emitMessageStatusUpdate(updatedMessage);
422→      }
423→
424→      return updatedMessage;
425→    } catch (error) {
426→      console.error('Error processing message status:', error);
427→      throw error;
428→    }
429→  }
