439→      console.log('Processing template status update:', JSON.stringify(value, null, 2));
440→
441→      // Extract template information from webhook payload
442→      const { message_template_id, message_template_name, event } = value;
443→
444→      if (!message_template_id || !event) {
445→        console.warn('Missing required fields in template status update');
446→        return {
447→          success: false,
448→          error: 'Missing required fields: message_template_id or event'
449→        };
450→      }
451→
452→      // Map Meta event to our status values
453→      const statusMap = {
454→        'APPROVED': 'approved',
455→        'REJECTED': 'rejected',
456→        'PENDING': 'pending',
457→        'DISABLED': 'rejected', // Treat disabled as rejected
458→        'PAUSED': 'pending', // Treat paused as pending
459→      };
460→
461→      const newStatus = statusMap[event];
462→      if (!newStatus) {
