464→        return {
465→          success: false,
466→          error: `Unknown event: ${event}`
467→        };
468→      }
469→
470→      // Find template by meta_template_id
471→      const template = await MessageTemplate.findOne({
472→        where: { meta_template_id: message_template_id.toString() },
