690→  /**
691→   * Verify webhook signature (Meta HMAC SHA256)
692→   * @param {string} signature - X-Hub-Signature-256 header value
693→   * @param {string} rawBody - Raw request body
694→   * @param {string} secret - Webhook secret from line configuration
695→   * @returns {boolean} Verification result
696→   */
697→  verifyWebhookSignature(signature, rawBody, secret) {
698→    try {
699→      if (!signature || !rawBody || !secret) {
700→        return false;
701→      }
702→
703→      // Extract the signature value (format: sha256=<signature>)
704→      const signatureHash = signature.replace('sha256=', '');
705→
706→      // Compute HMAC SHA256
707→      const expectedHash = crypto
708→        .createHmac('sha256', secret)
709→        .update(rawBody, 'utf8')
710→        .digest('hex');
711→
712→      // Constant-time comparison
713→      return crypto.timingSafeEqual(
714→        Buffer.from(signatureHash, 'hex'),
715→        Buffer.from(expectedHash, 'hex')
716→      );
717→    } catch (error) {
718→      console.error('Error verifying webhook signature:', error);
719→      return false;
720→    }
721→  }
722→}
