 273→      const urlButtons = formData.buttons.filter(btn => btn.type === 'URL');
 274→      const invalidUrlButtons = urlButtons.filter(btn => !btn.url);
 275→      if (invalidUrlButtons.length > 0) {
 276→        newErrors.buttons = 'Los botones URL requieren una URL valida';
