 351→
 352→    let prefix = '';
 353→    let suffix = '';
 354→
 355→    switch (formatType) {
 356→      case 'bold':
 357→        prefix = '*';
 358→        suffix = '*';
 359→        break;
 360→      case 'italic':
 361→        prefix = '_';
 362→        suffix = '_';
 363→        break;
 364→      case 'strikethrough':
 365→        prefix = '~';
 366→        suffix = '~';
 367→        break;
 368→      case 'code':
 369→        prefix = '```';
 370→        suffix = '```';
 371→        break;
 372→      default:
 373→        return;
 374→    }
 375→
 376→    const textBefore = formData.content.substring(0, start);
 377→    const textAfter = formData.content.substring(end);
 378→    const formattedText = prefix + selectedText + suffix;
 379→    const newContent = textBefore + formattedText + textAfter;
