  6→import { authorizeRole } from '../../../middleware/authorizeRole.js'
  7→const router = express.Router();
  8→
  9→/**
 10→ * POST /api/v1/templates
 11→ * Create a new template
 12→ * Body:
 13→ *  - lineId: WhatsApp line ID
 14→ *  - name: Template name
 15→ *  - content: Template content with {{1}}, {{2}}, etc. placeholders
 16→ *  - variables: Array of {name, type, example} objects
 17→ *  - submitToMeta: Boolean - whether to submit immediately (default: false)
 18→ */
 19→
 20→ 
 21→router.post('/',  authenticateJWT, authorizeRole(['admin', 'manager']), async (req, res, next) => {
 22→  try {
 23→    const {
 24→      lineId,
 25→      name,
 26→      content,
 27→      variables,
 28→      category = 'UTILITY',
 29→      language = 'es',
 30→      headerType = 'NONE',
 31→      headerContent,
 32→      headerExample,
 33→      headerCaption,
 34→      footerText,
 35→      buttons,
 36→      submitToMeta = false
 37→    } = req.body;
 38→
 39→    // Validation
 40→    if (!lineId || !name || !content) {
 41→      return res.status(400).json({
 42→        success: false,
 43→        error: 'Missing required fields: lineId, name, content'
 44→      });
 45→    }
 46→
 47→    // Validate category
 48→    if (!['AUTHENTICATION', 'MARKETING', 'UTILITY'].includes(category)) {
 49→      return res.status(400).json({
 50→        success: false,
 51→        error: 'Invalid category. Must be AUTHENTICATION, MARKETING, or UTILITY'
 52→      });
 53→    }
 54→
 55→    // Validate header type
 56→    if (!['NONE', 'TEXT', 'IMAGE', 'VIDEO', 'DOCUMENT', 'LOCATION'].includes(headerType)) {
 57→      return res.status(400).json({
 58→        success: false,
 59→        error: 'Invalid header type. Must be NONE, TEXT, IMAGE, VIDEO, DOCUMENT, or LOCATION'
 60→      });
 61→    }
 62→
 63→    // Validate header content length
 64→    if (headerType === 'TEXT' && headerContent && headerContent.length > 60) {
 65→      return res.status(400).json({
 66→        success: false,
 67→        error: 'Header text must be 60 characters or less'
 68→      });
 69→    }
 70→
 71→    // Validate footer text length
 72→    if (footerText && footerText.length > 60) {
 73→      return res.status(400).json({
 74→        success: false,
 75→        error: 'Footer text must be 60 characters or less'
 76→      });
 77→    }
 78→
 79→    // Validate buttons
 80→    if (buttons && buttons.length > 0) {
 81→      try {
 82→        TemplateManager._validateButtons(buttons);
 83→      } catch (buttonError) {
 84→        return res.status(400).json({
 85→          success: false,
 86→          error: buttonError.message
 87→        });
 88→      }
 89→    }
 90→
 91→    // Validate template format
 92→    const validation = TemplateService.validateTemplate(content, variables || []);
 93→    if (!validation.valid) {
 94→      return res.status(400).json({
 95→        success: false,
 96→        error: 'Template validation failed',
 97→        details: validation.errors
 98→      });
 99→    }
100→
101→    // Create template
102→    const template = await TemplateService.createTemplate({
103→      lineId,
104→      name,
105→      content,
106→      variables: variables || [],
107→      category,
108→      language,
109→      headerType,
110→      headerContent,
111→      headerExample,
112→      headerCaption,
113→      footerText,
114→      buttons: buttons || []
115→    });
116→
117→    // Submit to Meta if requested
118→    if (submitToMeta) {
119→      const line = await WhatsAppLine.findByPk(lineId);
120→      if (!line) {
121→        return res.status(404).json({
122→          success: false,
123→          error: 'WhatsApp line not found'
124→        });
125→      }
126→
127→      try {
128→        await TemplateManager.submitTemplate(template, line);
129→      } catch (metaError) {
130→        // Template created but Meta submission failed
131→        return res.status(201).json({
132→          success: true,
133→          data: template,
134→          warning: `Template created but Meta submission failed: ${metaError.message}`
135→        });
136→      }
137→    }
138→
139→    res.status(201).json({
140→      success: true,
141→      data: template
142→    });
143→  } catch (error) {
144→    next(error);
145→  }
146→});
147→
148→export default router;
