 1→/**
 2→ * POST /api/v1/templates/upload-media
 3→ *
 4→ * Upload media files for WhatsApp templates (IMAGE, VIDEO, DOCUMENT)
 5→ * Uses Meta's resumable upload to get valid handles for template examples
 6→ */
 7→
 8→import multer from 'multer';
 9→import { uploadRateLimiter } from '../../../middleware/rateLimiter.js';
10→import FileUploadService from '../../../services/FileUploadService.js';
11→import { AppError } from '../../../middleware/errorHandler.js';
12→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
13→import express from 'express';
14→
15→const router = express.Router();
16→
17→// Configure multer for memory storage
18→const upload = multer({
19→  storage: multer.memoryStorage(),
20→  limits: {
21→    fileSize: 100 * 1024 * 1024 // 100MB
22→  }
23→});
24→
25→/**
26→ * Upload media for template
27→ */
28→router.post(
29→  '/upload-media',
30→  authenticateJWT,
31→  uploadRateLimiter,
32→  upload.single('file'),
33→  async (req, res, next) => {
34→    try {
35→      const { lineId, mediaType } = req.body;
36→
37→      // Validate required fields
38→      if (!lineId) {
39→        throw new AppError('lineId is required', 400);
40→      }
41→
42→      if (!mediaType || !['image', 'document', 'video'].includes(mediaType)) {
43→        throw new AppError('mediaType is required and must be "image", "document", or "video"', 400);
44→      }
45→
46→      if (!req.file) {
47→        throw new AppError('No file provided', 400);
48→      }
49→
50→      // Check if user has access to this line
51→      if (req.user.role !== 'admin') {
52→        const hasAccess = req.user.assignedLines?.includes(parseInt(lineId));
53→
54→        if (!hasAccess) {
55→          throw new AppError('You do not have access to this WhatsApp line', 403);
56→        }
57→      }
58→
59→      let uploadResult;
60→
61→      // Upload file based on media type
62→      if (mediaType === 'image') {
63→        uploadResult = await FileUploadService.uploadImageForTemplate(req.file, lineId);
64→      } else if (mediaType === 'document') {
65→        uploadResult = await FileUploadService.uploadDocumentForTemplate(req.file, lineId);
66→      } else if (mediaType === 'video') {
67→        uploadResult = await FileUploadService.uploadVideoForTemplate(req.file, lineId);
68→      }
69→
70→      res.status(201).json({
71→        success: true,
72→        message: `${mediaType.charAt(0).toUpperCase() + mediaType.slice(1)} uploaded successfully for template`,
73→        data: {
74→          filename: uploadResult.filename,
75→          originalName: uploadResult.originalName || uploadResult.filename,
76→          publicUrl: uploadResult.publicUrl,
77→          handle: uploadResult.handle,
78→          mimeType: uploadResult.mimeType,
79→          size: uploadResult.size
80→        }
81→      });
82→    } catch (error) {
83→      next(error);
84→    }
85→  }
86→);
87→
88→export default router;
