 9→/**
10→ * PATCH /api/v1/templates/:templateId
11→ * Update a template
12→ * Body:
13→ *  - name: Updated name (optional)
14→ *  - content: Updated content (optional)
15→ *  - variables: Updated variables array (optional)
16→ *  - submitToMeta: Boolean - whether to submit to Meta after update
17→ */
18→router.patch('/:templateId', authenticateJWT, authorizeRole(['admin', 'manager']), async (req, res, next) => {
19→  try {
20→    const { templateId } = req.params;
21→    const { name, content, variables, submitToMeta = false } = req.body;
22→
23→    // Only admins and managers can update templates
24→    if (req.user.role !== 'admin' && req.user.role !== 'manager') {
25→      return res.status(403).json({
26→        success: false,
27→        error: 'Only administrators and managers can update templates'
28→      });
29→    }
30→
31→    // Validate if content and variables are provided together
32→    if (content && variables) {
33→      const validation = TemplateService.validateTemplate(content, variables);
34→      if (!validation.valid) {
35→        return res.status(400).json({
36→          success: false,
37→          error: 'Template validation failed',
38→          details: validation.errors
39→        });
40→      }
41→    }
42→
43→    // Update template
44→    const updates = {};
45→    if (name) updates.name = name;
46→    if (content) updates.content = content;
47→    if (variables) updates.variables = variables;
48→
49→    const template = await TemplateService.updateTemplate(parseInt(templateId), updates);
50→
51→    // Submit to Meta if requested
52→    if (submitToMeta) {
53→      const line = await WhatsAppLine.findByPk(template.line_id);
54→      if (!line) {
55→        return res.status(404).json({
56→          success: false,
57→          error: 'WhatsApp line not found'
58→        });
59→      }
60→
61→      try {
62→        await TemplateManager.submitTemplate(template, line);
63→      } catch (metaError) {
64→        return res.status(200).json({
65→          success: true,
66→          data: template,
67→          warning: `Template updated but Meta submission failed: ${metaError.message}`
68→        });
69→      }
70→    }
71→
72→    res.json({
73→      success: true,
74→      data: template
75→    });
76→  } catch (error) {
77→    if (error.message === 'Template not found') {
78→      return res.status(404).json({
79→        success: false,
80→        error: 'Template not found'
81→      });
82→    }
83→    next(error);
84→  }
85→});
