38→    const [results] = await pool.execute(sql, params);
39→    return results;
40→  } catch (error) {
41→    console.error('Database query error:', error);
42→    throw error;
43→  }
44→};
45→
46→// Helper function for transactions
47→export const transaction = async (callback) => {
48→  const connection = await pool.getConnection();
49→  try {
50→    await connection.beginTransaction();
51→    const result = await callback(connection);
52→    await connection.commit();
53→    return result;
54→  } catch (error) {
55→    await connection.rollback();
56→    throw error;
57→  } finally {
58→    connection.release();
59→  }
60→};
61→
62→// Graceful shutdown
63→process.on('SIGTERM', async () => {
64→  console.log('Closing database connection pool...');
65→  await pool.end();
66→  process.exit(0);
67→});
68→
69→// Export both Sequelize instance and legacy pool
70→export { sequelize, pool };
71→export default pool;
