import React from 'react';
import { Card, Button, Badge, Spinner } from 'react-bootstrap';
import './TemplateList.css';

const TemplateList = ({ templates, loading, onEdit, onDelete }) => {
  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: { bg: '#FDD8D8', color: '#7D1E1E', text: 'En revisión por meta' },
      approved: { bg: '#D4EDDA', color: '#155724', text: 'Aprobada' },
      rejected: { bg: '#F8D7DA', color: '#721C24', text: 'Rechazada' },
      draft: { bg: '#D1ECF1', color: '#0C5460', text: 'Borrador' }
    };

    const config = statusConfig[status] || statusConfig.draft;

    return (
      <Badge
        className="template-status-badge"
        style={{
          backgroundColor: config.bg,
          color: config.color
        }}
      >
        {config.text}
      </Badge>
    );
  };

  const truncateContent = (content, maxLength = 150) => {
    if (content.length <= maxLength) return content;
    return content.substring(0, maxLength) + '...';
  };

  if (loading) {
    return (
      <div className="template-list-loading">
        <Spinner animation="border" variant="primary" />
        <p className="mt-3">Cargando plantillas...</p>
      </div>
    );
  }

  if (templates.length === 0) {
    return (
      <div className="template-list-empty">
        <i className="bi bi-file-text template-empty-icon"></i>
        <h5>No hay plantillas</h5>
        <p>Crea tu primera plantilla para comenzar</p>
      </div>
    );
  }

  return (
    <div className="template-list-container">
      <div className="template-list-grid">
        {templates.map((template) => (
          <Card key={template.id} className="template-card">
            <Card.Body className="template-card-body">
              <div className="template-card-content">
                <div className="template-card-header">
                  <h6 className="template-card-title">{template.name}</h6>
                  {getStatusBadge(template.status)}
                </div>
                <p className="template-card-text">
                  {truncateContent(template.content)}
                </p>
                {template.line && (
                  <p className="template-card-line">
                    <i className="bi bi-whatsapp me-1"></i>
                    {template.line.company_name}
                  </p>
                )}
              </div>

              {/* Mostrar botones solo si tiene permisos y no está en revisión por Meta */}
              {(onEdit || onDelete) && template.status !== 'pending' && (
                <div className="template-card-actions">
                  {onEdit && (
                    <Button
                      variant="outline-dark"
                      className="template-action-btn"
                      onClick={() => onEdit(template)}
                      title="Editar"
                    >
                      <i className="bi bi-pencil"></i>
                    </Button>
                  )}
                  {onDelete && (
                    <Button
                      variant="outline-danger"
                      className="template-action-btn template-delete-btn"
                      onClick={() => onDelete(template)}
                      title="Eliminar"
                    >
                      <i className="bi bi-trash"></i>
                    </Button>
                  )}
                </div>
              )}
            </Card.Body>
          </Card>
        ))}
      </div>
    </div>
  );
};

export default TemplateList;

