async processTemplateStatusUpdate(value) {
  try {
    console.log('Processing template status update:', JSON.stringify(value, null, 2));

    // Extract template information from webhook payload
    const { message_template_id, message_template_name, event } = value;

    if (!message_template_id || !event) {
      console.warn('Missing required fields in template status update');
      return {
        success: false,
        error: 'Missing required fields: message_template_id or event'
      };
    }

    // Map Meta event to our status values
    const statusMap = {
      'APPROVED': 'approved',
      'REJECTED': 'rejected',
      'PENDING': 'pending',
      'DISABLED': 'rejected', // Treat disabled as rejected
      'PAUSED': 'pending', // Treat paused as pending
    };

    const newStatus = statusMap[event];
    if (!newStatus) {
      console.warn(`Unknown template status event: ${event}`);
      return {
        success: false,
        error: `Unknown event: ${event}`
      };
    }

    // Find template by meta_template_id
    const template = await MessageTemplate.findOne({
      where: { meta_template_id: message_template_id.toString() },
      include: [{
        model: WhatsAppLine,
        as: 'line'
      }]
    });

    if (!template) {
      // Template might not exist yet if this is a very quick response
      // or if template was created directly in Meta's dashboard
      console.warn(`Template not found for meta_template_id: ${message_template_id}`);
      return {
        success: false,
        error: `Template not found: ${message_template_id}`
      };
    }

    // Update template status
    const previousStatus = template.status;
    await template.update({
      status: newStatus,
      rejection_reason: event === 'REJECTED' ?
        (value.rejection_reason || 'Template rejected by Meta') :
        null
    });

    console.log(`Template ${template.id} status updated: ${previousStatus} → ${newStatus}`);

    // Emit Socket.IO event for real-time notification
    if (SocketService.emitTemplateStatusUpdate) {
      SocketService.emitTemplateStatusUpdate(template.line_id, {
        template_id: template.id,
        template_name: template.name,
        status: newStatus,
        previous_status: previousStatus,
        rejection_reason: template.rejection_reason,
        meta_template_id: message_template_id
      });
    }

    return {
      success: true,
      template_id: template.id,
      template_name: template.name,
      previous_status: previousStatus,
      new_status: newStatus
    };
  } catch (error) {
    console.error('Error processing template status update:', error);
    return {
      success: false,
      error: error.message
    };
  }
}

