/* Template List Styles - Based on Figma Design */

.template-list-container {
  width: 100%;
}

.template-list-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  width: 100%;
}

.template-card {
  background: white;
  border: 1px solid #909093;
  border-radius: 12px;
  transition: box-shadow 0.2s;
  overflow: visible;
}

.template-card:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.template-card-body {
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 24px;
}

.template-card-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.template-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.template-card-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  color: #1C1C1D;
  margin: 0;
  flex: 1;
  min-width: 0;
}

.template-status-badge {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  padding: 6px 12px;
  border-radius: 4px;
  letter-spacing: 0.07px;
}

.template-card-text {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #4D4D4F;
  margin: 0;
  letter-spacing: 0.08px;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.template-card-line {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 12px;
  line-height: 16px;
  color: #909093;
  margin: 4px 0 0 0;
  display: flex;
  align-items: center;
}

.template-card-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.template-action-btn {
  width: 44px;
  height: 44px;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-size: 20px;
  transition: all 0.2s;
}

.template-action-btn:hover {
  transform: scale(1.05);
}

.template-delete-btn {
  border-color: #F73B3B;
  color: #F73B3B;
}

.template-delete-btn:hover {
  background-color: #F73B3B;
  border-color: #F73B3B;
  color: white;
}

.template-list-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}

.template-list-loading p {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  color: #4D4D4F;
}

.template-list-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}

.template-empty-icon {
  font-size: 64px;
  color: #909093;
  margin-bottom: 16px;
}

.template-list-empty h5 {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 20px;
  color: #1C1C1D;
  margin-bottom: 8px;
}

.template-list-empty p {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  color: #4D4D4F;
}

/* Responsive adjustments */
@media (min-width: 768px) {
  .template-list-grid {
    grid-template-columns: 1fr;
  }
}

 .template-card-rejection {
    font-size: 0.8rem;
    color: #721C24;
    background-color: #F8D7DA;
    padding: 6px 10px;
    border-radius: 4px;
    margin-bottom: 8px;
  }

'use strict';

/**
 * Migration: Create message_templates table
 *
 * WhatsApp message templates configured for the platform and approved by Meta
 * for business-initiated conversations.
 *
 * Dependencies: whatsapp_lines table must exist
 *
 * @type {import('sequelize-cli').Migration}
 */
module.exports = {
  async up(queryInterface, Sequelize) {
    await queryInterface.createTable('message_templates', {
      id: {
        type: Sequelize.INTEGER,
        primaryKey: true,
        autoIncrement: true,
        allowNull: false,
      },
      line_id: {
        type: Sequelize.INTEGER,
        allowNull: false,
        references: {
          model: 'whatsapp_lines',
          key: 'id',
        },
        onUpdate: 'CASCADE',
        onDelete: 'CASCADE',
        comment: 'WhatsApp line this template belongs to',
      },
      name: {
        type: Sequelize.STRING(100),
        allowNull: false,
        comment: 'Template name',
      },
      content: {
        type: Sequelize.TEXT,
        allowNull: false,
        comment: 'Template message content with variable placeholders',
      },
      variables: {
        type: Sequelize.JSON,
        allowNull: true,
        comment: 'Array of variable definitions: [{"name": "customer_name", "type": "text"}]',
      },
      meta_template_id: {
        type: Sequelize.STRING(255),
        allowNull: true,
        comment: "Meta's template ID after approval",
      },
      status: {
        type: Sequelize.ENUM('draft', 'pending', 'approved', 'rejected'),
        allowNull: false,
        defaultValue: 'draft',
        comment: 'Template approval status',
      },
      rejection_reason: {
        type: Sequelize.TEXT,
        allowNull: true,
        comment: "Meta's rejection reason if status is rejected",
      },
      created_at: {
        type: Sequelize.DATE,
        allowNull: false,
        defaultValue: Sequelize.literal('CURRENT_TIMESTAMP'),
      },
      updated_at: {
        type: Sequelize.DATE,
        allowNull: false,
        defaultValue: Sequelize.literal('CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP'),
      },
    }, {
      charset: 'utf8mb4',
      collate: 'utf8mb4_unicode_ci',
      engine: 'InnoDB',
      comment: 'WhatsApp message templates for business-initiated conversations',
    });

    // Create indexes
    await queryInterface.addIndex('message_templates', ['line_id'], {
      name: 'idx_templates_line',
    });

    await queryInterface.addIndex('message_templates', ['status'], {
      name: 'idx_templates_status',
    });

    await queryInterface.addIndex('message_templates', ['meta_template_id'], {
      name: 'idx_templates_meta_id',
    });

    await queryInterface.addIndex('message_templates', ['line_id', 'name'], {
      name: 'idx_templates_line_name',
      unique: true,
    });
  },

  async down(queryInterface, Sequelize) {
    await queryInterface.dropTable('message_templates');
  }
};

