/* Template List Styles - Based on Figma Design */

.template-list-container {
  width: 100%;
}

.template-list-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  width: 100%;
}

.template-card {
  background: white;
  border: 1px solid #909093;
  border-radius: 12px;
  transition: box-shadow 0.2s;
  overflow: visible;
}

.template-card:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.template-card-body {
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 24px;
}

.template-card-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.template-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.template-card-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  color: #1C1C1D;
  margin: 0;
  flex: 1;
  min-width: 0;
}

.template-status-badge {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  padding: 6px 12px;
  border-radius: 4px;
  letter-spacing: 0.07px;
}

