/* Template List Styles - Based on Figma Design */

.template-list-container {
  width: 100%;
}

.template-list-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  width: 100%;
}

.template-card {
  background: white;
  border: 1px solid #909093;
  border-radius: 12px;
  transition: box-shadow 0.2s;
  overflow: visible;
}

.template-card:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.template-card-body {
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 24px;
}

.template-card-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.template-card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.template-card-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  color: #1C1C1D;
  margin: 0;
  flex: 1;
  min-width: 0;
}

.template-status-badge {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  line-height: 20px;
  padding: 6px 12px;
  border-radius: 4px;
  letter-spacing: 0.07px;
}

.template-card-text {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #4D4D4F;
  margin: 0;
  letter-spacing: 0.08px;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.template-card-line {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 12px;
  line-height: 16px;
  color: #909093;
  margin: 4px 0 0 0;
  display: flex;
  align-items: center;
}

.template-card-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.template-action-btn {
  width: 44px;
  height: 44px;
  border-radius: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-size: 20px;
  transition: all 0.2s;
}

.template-action-btn:hover {
  transform: scale(1.05);
}

.template-delete-btn {
  border-color: #F73B3B;
  color: #F73B3B;
}

.template-delete-btn:hover {
  background-color: #F73B3B;
  border-color: #F73B3B;
  color: white;
}

.template-list-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}

.template-list-loading p {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 16px;
  color: #4D4D4F;
}

.template-list-empty {
